 const pmrem=new THREE.PMREMGenerator(renderer),room=new RoomEnvironment(),environment=pmrem.fromScene(room,.04).texture;scene.environment=environment;scene.environmentIntensity=.5;room.dispose();pmrem.dispose();
 scene.add(new THREE.HemisphereLight(0xbac9ff,0x100b25,.85));
 const key=new THREE.DirectionalLight(0xffeddc,2.7);key.position.set(-3,5,7);scene.add(key);
 const cyan=new THREE.DirectionalLight(0x8cb7f1,.65);cyan.position.set(-6,-1,1);scene.add(cyan);
