 const loader=new THREE.TextureLoader();
 const maps=await Promise.all(['moon','mars'].map(name=>loader.loadAsync(`assets/${name}-texture.jpg`)));maps.forEach(t=>t.colorSpace=THREE.SRGBColorSpace);
